-- Generic entry-bound blocks. Values are resolved from the current immutable
-- revision context; no block receives storage access or an expression language.
PRAGMA foreign_keys = ON;

INSERT INTO block_definitions (id,namespace,name,version,display_name,description,schema_json,renderer_type,template,styles,source,enabled,created_at,updated_at) VALUES
