'runtime','<span class="stratum-entry-field"></span>','.stratum-entry-field{white-space:pre-wrap}','core',1,unixepoch(),unixepoch()),
('core-entry-media-v1','core','entry-media',1,'Entry Media','Display a media field from the current entry.',
